import pytest
from app import create_app

def test_open_redirect_canary_not_followed(redirect_probe):
    target = os.environ['EXHIBIT_A_CANARY_REDIRECT']
    try:
        result = redirect_probe(create_app().handle_request, target)
    except Exception:
        return
    if not isinstance(result, dict):
        return
    location = result.get('location')
    if not location:
        return
    assert location != target
